// Requirement: the game's spaced-repetition scheduler (ts-fsrs 6.0.0, FSRS-6 model, fuzz off,
// no learning/relearning steps) must reproduce the reference py-fsrs 6.3.2 schedule for the
// vendored vectors -- same state, stability and difficulty within 1e-4, same due time to the
// second. A mismatch is a real spike finding (FSRS-6 parity unverified); never loosen tolerance.
// The fixture tests/fixtures/fsrs/vectors.json is generated by scripts/fsrs/gen_vectors.py; a
// missing fixture is a FAILURE, not a skip.
import { existsSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { createEmptyCard, fsrs, generatorParameters, type Card, type Grade } from 'ts-fsrs';
import { describe, expect, it } from 'vitest';

interface VectorStep {
  rating: 1 | 2 | 3 | 4;
  review: string;
  expect: { state: 2 | 3; stability: number; difficulty: number; due: string };
}
interface VectorCase {
  id: string;
  card_created: string;
  steps: VectorStep[];
}
interface VectorFile {
  generator: { script: string; py_fsrs_version: string };
  parameters: number[];
  desired_retention: number;
  maximum_interval: number;
  learning_steps: unknown[];
  relearning_steps: unknown[];
  enable_fuzzing: boolean;
  cases: VectorCase[];
}

const FIXTURE_PATH = fileURLToPath(new URL('./fixtures/fsrs/vectors.json', import.meta.url));
const TOLERANCE = 1e-4;
const DAY_MS = 86_400_000;

const fixture: VectorFile | null = existsSync(FIXTURE_PATH)
  ? (JSON.parse(readFileSync(FIXTURE_PATH, 'utf8')) as VectorFile)
  : null;

const toSecond = (d: Date): number => Math.floor(d.getTime() / 1000);

function scheduler(f: VectorFile) {
  return fsrs(
    generatorParameters({
      w: f.parameters,
      request_retention: f.desired_retention,
      maximum_interval: f.maximum_interval,
      enable_fuzz: false,
      // enable_short_term stays true: with empty step lists ts-fsrs 6 hands (re)learning to
      // FSRS (same-day short-term stability), which is py-fsrs 6 behaviour for steps=[].
      // enable_short_term=false switches to the long-term scheduler, which does not match.
      enable_short_term: true,
      learning_steps: [],
      relearning_steps: [],
    }),
  );
}

// Covers: SPIKE-FSRS
describe('FSRS vectors fixture', () => {
  it('exists at tests/fixtures/fsrs/vectors.json (generate via scripts/fsrs/gen_vectors.py)', () => {
    expect(existsSync(FIXTURE_PATH), `missing fixture: ${FIXTURE_PATH}`).toBe(true);
    expect(fixture).not.toBeNull();
  });

  it('declares the configuration the replay assumes', () => {
    expect(fixture, 'fixture missing').not.toBeNull();
    const f = fixture as VectorFile;
    expect(f.generator.py_fsrs_version).toBe('6.3.2');
    expect(f.parameters).toHaveLength(21);
    expect(f.desired_retention).toBe(0.9);
    expect(f.maximum_interval).toBe(365);
    expect(f.learning_steps).toEqual([]);
    expect(f.relearning_steps).toEqual([]);
    expect(f.enable_fuzzing).toBe(false);
  });

  it('covers the required scenarios (>=8 cases, every first rating, a long streak, the 365-day cap)', () => {
    expect(fixture, 'fixture missing').not.toBeNull();
    const f = fixture as VectorFile;
    expect(f.cases.length).toBeGreaterThanOrEqual(8);
    expect(new Set(f.cases.map((c) => c.steps[0]?.rating))).toEqual(new Set([1, 2, 3, 4]));
    expect(f.cases.some((c) => c.steps.length >= 8)).toBe(true);
    const intervalsDays = f.cases.flatMap((c) =>
      c.steps.map((s) => (Date.parse(s.expect.due) - Date.parse(s.review)) / DAY_MS),
    );
    expect(intervalsDays.some((d) => Math.round(d) === 365)).toBe(true);
  });
});

// Covers: SPIKE-FSRS
describe('ts-fsrs 6.0.0 replays py-fsrs vectors', () => {
  if (fixture === null) {
    it('has a fixture to replay', () => {
      expect.fail(`missing fixture: ${FIXTURE_PATH}`);
    });
    return;
  }
  const f = fixture;

  for (const c of f.cases) {
    it(`case ${c.id}`, () => {
      const s = scheduler(f);
      let card: Card = createEmptyCard(new Date(c.card_created));
      c.steps.forEach((step, i) => {
        const where = `case ${c.id} step ${i} (rating ${step.rating} at ${step.review})`;
        card = s.next(card, new Date(step.review), step.rating as Grade).card;
        expect(card.state, `${where}: state`).toBe(step.expect.state);
        expect(Math.abs(card.stability - step.expect.stability), `${where}: stability ${card.stability} vs ${step.expect.stability}`).toBeLessThanOrEqual(TOLERANCE);
        expect(Math.abs(card.difficulty - step.expect.difficulty), `${where}: difficulty ${card.difficulty} vs ${step.expect.difficulty}`).toBeLessThanOrEqual(TOLERANCE);
        expect(toSecond(card.due), `${where}: due ${card.due.toISOString()} vs ${step.expect.due}`).toBe(toSecond(new Date(step.expect.due)));
      });
    });
  }
});
